        def __init__(
            self,
            companyName: Union[str, CompanyName],
            street: Iterable[Union[str, Street]],
            zIPCode: Union[str, ZIPCode],
            city: Union[str, City],
            nationalCode: Union[str, NationalCode],
            customerRole: Optional[Iterable[Union[str, CustomerRole]]] = None,
            mailAddress: Optional[Iterable[Union[str, MailAddress]]] = None,
            id_short: Optional[str] = r"Customer",
            display_name: Optional[
                aas.MultiLanguageNameType
            ] = aas.MultiLanguageNameType(dict_={r"de": r"Kunde", r"en": r"Customer"}),
            category: Optional[str] = None,
            description: Optional[aas.MultiLanguageTextType] = None,
            semantic_id: Optional[aas.Reference] = aas.ExternalReference(
                key=(
                    aas.Key(
                        type_=aas.KeyTypes.GLOBAL_REFERENCE,
                        value=r"https://admin-shell.io/idta/InspectionDocumentsOfSteelProducts/Customer/1/0",
                    ),
                ),
                referred_semantic_id=None,
            ),
            qualifier: Iterable[aas.Qualifier] = None,
            extension: Iterable[aas.Extension] = (),
            supplemental_semantic_id: Iterable[aas.Reference] = (),
            embedded_data_specifications: Iterable[
                aas.EmbeddedDataSpecification
            ] = None,
        ):

            if qualifier is None:
                qualifier = (
                    aas.Qualifier(
                        type_=r"SMT/Cardinality",
                        value_type=str,
                        value=r"OneToMany",
                        value_id=None,
                        kind=aas.QualifierKind.TEMPLATE_QUALIFIER,
                        semantic_id=aas.ExternalReference(
                            key=(
                                aas.Key(
                                    type_=aas.KeyTypes.GLOBAL_REFERENCE,
                                    value=r"https://admin-shell.io/SubmodelTemplates/Cardinality/1/0",
                                ),
                            ),
                            referred_semantic_id=None,
                        ),
                        supplemental_semantic_id=(),
                    ),
                )

            if embedded_data_specifications is None:
                embedded_data_specifications = []

            # Build a submodel element if a raw value was passed in the argument

            if companyName is not None and not isinstance(
                companyName, aas.SubmodelElement
            ):
                companyName = self.CompanyName(companyName)

            # Build submodel elements from raw values passed in the argument
            if customerRole:
                customerRole = [
                    i if isinstance(i, aas.SubmodelElement) else self.CustomerRole(i)
                    for i in customerRole
                ]

            # Build submodel elements from raw values passed in the argument
            if street:
                street = [
                    i if isinstance(i, aas.SubmodelElement) else self.Street(i)
                    for i in street
                ]

            # Build a submodel element if a raw value was passed in the argument

            if zIPCode is not None and not isinstance(zIPCode, aas.SubmodelElement):
                zIPCode = self.ZIPCode(zIPCode)

            # Build a submodel element if a raw value was passed in the argument

            if city is not None and not isinstance(city, aas.SubmodelElement):
                city = self.City(city)

            # Build a submodel element if a raw value was passed in the argument

            if nationalCode is not None and not isinstance(
                nationalCode, aas.SubmodelElement
            ):
                nationalCode = self.NationalCode(nationalCode)

            # Build submodel elements from raw values passed in the argument
            if mailAddress:
                mailAddress = [
                    i if isinstance(i, aas.SubmodelElement) else self.MailAddress(i)
                    for i in mailAddress
                ]

            # Add all passed/initialized submodel elements to a single list
            embedded_submodel_elements = []
            for se_arg in [
                companyName,
                customerRole,
                street,
                zIPCode,
                city,
                nationalCode,
                mailAddress,
            ]:
                if se_arg is None:
                    continue
                elif isinstance(se_arg, aas.SubmodelElement):
                    embedded_submodel_elements.append(se_arg)
                elif isinstance(se_arg, Iterable):
                    for n, element in enumerate(se_arg):
                        element.id_short = f"{element.id_short}{n}"
                        embedded_submodel_elements.append(element)
                else:
                    raise TypeError(
                        f"Unknown type of value in submodel_element_args: {se_arg.__class__}"
                    )

            super().__init__(
                value=embedded_submodel_elements,
                id_short=id_short,
                display_name=display_name,
                category=category,
                description=description,
                semantic_id=semantic_id,
                qualifier=qualifier,
                extension=extension,
                supplemental_semantic_id=supplemental_semantic_id,
                embedded_data_specifications=embedded_data_specifications,
            )

